import { createContext, useContext, useEffect, useMemo, useState } from "react";
import lg from "./lg.json";
import lgOverrides from "./lg.overrides.json";

export type Language = "en" | "lg";

// UI text is written in English in the code as t("..."). The Luganda versions in lg.json are
// generated by Sunbird with `npm run translate-ui` in server/. Short labels that Sunbird got wrong
// without context are corrected in lg.overrides.json (translated by Sunbird as fuller phrases).
const dictionary = { ...(lg as Record<string, string>), ...(lgOverrides as Record<string, string>) };

type Ctx = { language: Language; setLanguage: (l: Language) => void; t: (english: string) => string };

const LanguageContext = createContext<Ctx>({ language: "en", setLanguage: () => {}, t: (s) => s });

export function LanguageProvider({ children }: { children: React.ReactNode }) {
  const [language, setLanguage] = useState<Language>(() => {
    try {
      return localStorage.getItem("eddembe.language") === "lg" ? "lg" : "en";
    } catch {
      return "en";
    }
  });
  useEffect(() => {
    try {
      localStorage.setItem("eddembe.language", language);
    } catch {
      /* private mode: language just is not remembered */
    }
    document.documentElement.lang = language === "lg" ? "lg" : "en";
  }, [language]);

  const value = useMemo<Ctx>(
    () => ({ language, setLanguage, t: (s) => (language === "lg" ? dictionary[s] ?? s : s) }),
    [language]
  );
  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}

export const useLanguage = () => useContext(LanguageContext);

// ---- Translating results from the server (answers, scan results, letters) ----

const cache = new Map<string, string>(); // English -> Luganda

// Lets a page store translations the server already made, so they are not requested again.
export function rememberTranslations(english: string[], luganda: string[]) {
  english.forEach((e, i) => luganda[i] && cache.set(e, luganda[i]));
}

async function fetchTranslations(texts: string[]): Promise<void> {
  const missing = [...new Set(texts.filter((t) => t.trim() && !cache.has(t)))];
  for (let i = 0; i < missing.length; i += 50) {
    const batch = missing.slice(i, i + 50);
    const res = await fetch("/api/translate", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ texts: batch, target: "lg" }),
    });
    if (!res.ok) throw new Error("translate failed");
    const data = (await res.json()) as { texts: string[] };
    batch.forEach((t, j) => cache.set(t, data.texts[j] ?? t));
  }
}

// Returns the texts in the current language. While Luganda is loading, shows English.
export function useTranslated(english: string[]): { texts: string[]; translating: boolean; failed: boolean } {
  const { language } = useLanguage();
  const key = english.join("\u0000");
  const [, force] = useState(0);
  const [translating, setTranslating] = useState(false);
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    if (language !== "lg" || english.every((t) => !t.trim() || cache.has(t))) return;
    let live = true;
    setTranslating(true);
    setFailed(false);
    fetchTranslations(english)
      .catch(() => live && setFailed(true))
      .finally(() => {
        if (!live) return;
        setTranslating(false);
        force((n) => n + 1);
      });
    return () => {
      live = false;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [language, key]);

  if (language !== "lg") return { texts: english, translating: false, failed: false };
  return { texts: english.map((t) => cache.get(t) ?? t), translating, failed };
}
